grant insert(blocker_id,blocked_id) on public.user_blocks to authenticated;
grant delete on public.user_blocks to authenticated;
grant insert(conversation_id,reporter_id,reason,details) on public.conversation_reports to authenticated;
grant usage on sequence public.messages_id_seq to authenticated;
grant all on public.favourites,public.conversations,public.messages,public.user_blocks,public.conversation_reports to service_role;
grant usage, select on sequence public.messages_id_seq to service_role;

create policy favourites_read on public.favourites for select to authenticated using(user_id=(select auth.uid()));
create policy favourites_add on public.favourites for insert to authenticated with check(
  user_id=(select auth.uid()) and (select public.is_verified_seller()) and exists(select 1 from public.listings l where l.id=listing_id and l.status='active')
);
create policy favourites_remove on public.favourites for delete to authenticated using(user_id=(select auth.uid()));
create policy conversations_read on public.conversations for select to authenticated using((select auth.uid()) in (buyer_id,seller_id));
create policy conversations_add on public.conversations for insert to authenticated with check(
  buyer_id=(select auth.uid()) and (select public.is_verified_seller())
  and exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=conversations.seller_id and l.status='active')
);
create policy messages_read on public.messages for select to authenticated using(
  exists(select 1 from public.conversations c where c.id=conversation_id and (select auth.uid()) in(c.buyer_id,c.seller_id))
);
create policy messages_add on public.messages for insert to authenticated with check(
  sender_id=(select auth.uid()) and (select public.is_verified_seller()) and
  exists(select 1 from public.conversations c where c.id=conversation_id and (select auth.uid()) in(c.buyer_id,c.seller_id))
);
-- Block status is visible only to the two affected people; only its creator can remove it.
create policy blocks_read on public.user_blocks for select to authenticated using((select auth.uid()) in(blocker_id,blocked_id));
create policy blocks_add on public.user_blocks for insert to authenticated with check(
  blocker_id=(select auth.uid()) and (select public.is_verified_seller()) and exists(
    select 1 from public.conversations c where (c.buyer_id=blocker_id and c.seller_id=blocked_id) or (c.seller_id=blocker_id and c.buyer_id=blocked_id))
);
create policy blocks_remove on public.user_blocks for delete to authenticated using(blocker_id=(select auth.uid()));
create policy reports_read on public.conversation_reports for select to authenticated using(reporter_id=(select auth.uid()));
create policy reports_add on public.conversation_reports for insert to authenticated with check(
  reporter_id=(select auth.uid()) and (select public.is_verified_seller()) and exists(
    select 1 from public.conversations c where c.id=conversation_id and (select auth.uid()) in(c.buyer_id,c.seller_id))
);

-- Invoker triggers preserve RLS. Pair locks serialize message/block writes;
-- actor locks prevent concurrent requests from bypassing per-account limits.
create function private.guard_social_write() returns trigger language plpgsql set search_path='' as $$
declare actor uuid := auth.uid(); a uuid; b uuid; thread public.conversations; n integer;
begin
  if actor is null or not public.is_verified_seller() then raise insufficient_privilege; end if;
  perform pg_advisory_xact_lock(hashtextextended('social-actor:'||actor::text,0));
  if tg_table_name='conversations' then
    if new.buyer_id<>actor then raise insufficient_privilege; end if;
    a:=new.buyer_id; b:=new.seller_id;
    select l.brand||' '||l.name into new.listing_title from public.listings l where l.id=new.listing_id and l.seller_id=b and l.status='active';
    if new.listing_title is null then raise insufficient_privilege; end if;
    select count(*) into n from public.conversations where buyer_id=actor and created_at>now()-interval '1 hour';
    if n>=10 then raise exception 'Rate limit'; end if;
  elsif tg_table_name='messages' then
    if new.sender_id<>actor then raise insufficient_privilege; end if;
    select * into thread from public.conversations where id=new.conversation_id;
    if thread.id is null or actor not in(thread.buyer_id,thread.seller_id) then raise insufficient_privilege; end if;
    a:=thread.buyer_id; b:=thread.seller_id;
    select count(*) into n from public.messages where sender_id=actor and created_at>now()-interval '1 minute';
    if n>=20 then raise exception 'Rate limit'; end if;
  elsif tg_table_name='user_blocks' then
    if tg_op='DELETE' then a:=old.blocker_id; b:=old.blocked_id; else a:=new.blocker_id; b:=new.blocked_id; end if;
    if a<>actor then raise insufficient_privilege; end if;
  elsif tg_table_name='conversation_reports' then
    if new.reporter_id<>actor then raise insufficient_privilege; end if;
    select count(*) into n from public.conversation_reports where reporter_id=actor and created_at>now()-interval '1 hour';
    if n>=5 then raise exception 'Rate limit'; end if;
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('social-pair:'||least(a,b)::text||greatest(a,b)::text,0));
  if tg_table_name in ('messages','conversations') and exists(select 1 from public.user_blocks where (blocker_id=a and blocked_id=b) or (blocker_id=b and blocked_id=a)) then
    raise insufficient_privilege;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$$;
revoke all on function private.guard_social_write() from public,anon,authenticated;
create trigger conversations_guard before insert on public.conversations for each row execute function private.guard_social_write();
create trigger messages_guard before insert on public.messages for each row execute function private.guard_social_write();
create trigger blocks_guard before insert or delete on public.user_blocks for each row execute function private.guard_social_write();
create trigger reports_guard before insert on public.conversation_reports for each row execute function private.guard_social_write();
commit;

-- ===== 20261117120902_harden_function_permissions.sql =====
begin;

-- Supabase defaults grant client roles explicitly; revoking PUBLIC alone is insufficient.
-- Existing triggers continue to run without client EXECUTE permission.
revoke execute on function public.create_user_profile() from public, anon, authenticated;
revoke execute on function public.set_updated_at() from public, anon, authenticated;
revoke execute on function public.queue_photo_cleanup() from public, anon, authenticated;

-- RLS and social-write guards need this current-user-only check for signed-in users.
revoke execute on function public.is_verified_seller() from public, anon;
grant execute on function public.is_verified_seller() to authenticated;

commit;

-- ===== 20261117123645_test_checkout_orders.sql =====
begin;
create schema if not exists private;
create table private.test_checkout_settings (
  singleton boolean primary key default true check(singleton),
  enabled boolean not null default true,
  fee_pence integer not null check(fee_pence between 0 and 100000),
  delivery_pence integer not null check(delivery_pence between 0 and 100000)
);
insert into private.test_checkout_settings values(true,true,250,595);
alter table private.test_checkout_settings enable row level security;
revoke all on private.test_checkout_settings from public,anon,authenticated;

-- Isolated inventory: simulated purchases never reserve or sell real listings.
create table public.test_listings (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid not null references public.profiles(id) on delete cascade,
  title text not null check(char_length(btrim(title)) between 1 and 70),
  price_pence integer not null check(price_pence between 100 and 2000000),
  status text not null default 'active' check(status in ('active','reserved','sold')),
  reserved_until timestamptz,
  created_at timestamptz not null default now()
);
create table public.test_orders (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.test_listings(id) on delete cascade,
  buyer_id uuid not null references public.profiles(id) on delete cascade,
  seller_id uuid not null references public.profiles(id) on delete cascade,
  request_id uuid not null,
  title text not null,
  item_pence integer not null,
  fee_pence integer not null,
  delivery_pence integer not null,
  total_pence integer generated always as (item_pence+fee_pence+delivery_pence) stored,
  status text not null check(status in ('reserved','paid','dispatched','delivered','failed','cancelled','expired')),
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(buyer_id,request_id),
  check(buyer_id<>seller_id)
);
create unique index test_orders_one_sale on public.test_orders(listing_id)
  where status in ('reserved','paid','dispatched','delivered');
create index test_orders_seller on public.test_orders(seller_id,created_at desc);
create index test_orders_buyer on public.test_orders(buyer_id,created_at desc);
create index test_listings_seller on public.test_listings(seller_id);
alter table public.test_listings enable row level security;
alter table public.test_orders enable row level security;
revoke all on public.test_listings,public.test_orders from public,anon,authenticated;
grant select on public.test_listings,public.test_orders to authenticated;
grant all on public.test_listings,public.test_orders to service_role;
create policy test_inventory_read on public.test_listings for select to authenticated using(true);
create policy test_order_participants on public.test_orders for select to authenticated
  using(buyer_id=(select auth.uid()) or seller_id=(select auth.uid()));

create function private.test_checkout(p_action text,p_listing uuid,p_request uuid,p_order uuid,p_title text,p_price integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  actor uuid := auth.uid();
  item public.test_listings;
  ord public.test_orders;
  settings private.test_checkout_settings;
begin
  if actor is null or not public.is_verified_seller() then
    raise exception 'Confirm your email before testing checkout' using errcode='42501';
  end if;
  select * into settings from private.test_checkout_settings where singleton;
  if not settings.enabled then raise exception 'Test checkout is disabled' using errcode='42501'; end if;
  if p_action='create' then
    perform pg_advisory_xact_lock(hashtextextended(actor::text,1));
    if (select count(*) from public.test_listings where seller_id=actor and created_at>now()-interval '1 hour')>=10 then
      raise exception 'Test listing limit reached' using errcode='P0001';
    end if;
    insert into public.test_listings(seller_id,title,price_pence) values(actor,p_title,p_price) returning * into item;
    return to_jsonb(item);
  end if;
  if p_action in ('quote','reserve') then
    select * into item from public.test_listings where id=p_listing for update;
  else
    select * into ord from public.test_orders where id=p_order and actor in (buyer_id,seller_id);
    if not found then raise exception 'Order unavailable' using errcode='42501'; end if;
    select * into item from public.test_listings where id=ord.listing_id for update;
  end if;
  if item.id is null then raise exception 'Test listing unavailable' using errcode='42501'; end if;
  update public.test_orders set status='expired',updated_at=now()
    where listing_id=item.id and status='reserved' and expires_at<=now();
  if item.status='reserved' and item.reserved_until<=now() then
    update public.test_listings set status='active',reserved_until=null where id=item.id returning * into item;
  end if;
  if p_action in ('quote','reserve') then
    if item.seller_id=actor then raise exception 'You cannot buy your own listing' using errcode='42501'; end if;
    if p_action='reserve' then
      if p_request is null then raise exception 'Request ID required' using errcode='22023'; end if;
      select * into ord from public.test_orders where buyer_id=actor and request_id=p_request;
      if found then
        if ord.listing_id<>item.id then raise exception 'Request already used' using errcode='23505'; end if;
        return to_jsonb(ord);
      end if;
    end if;
    if item.status<>'active' then raise exception 'Test item already reserved or sold' using errcode='23505'; end if;
    if p_action='quote' then
      return jsonb_build_object('title',item.title,'item_pence',item.price_pence,'fee_pence',settings.fee_pence,
        'delivery_pence',settings.delivery_pence,'total_pence',item.price_pence+settings.fee_pence+settings.delivery_pence);
    end if;
    insert into public.test_orders(listing_id,buyer_id,seller_id,request_id,title,item_pence,fee_pence,delivery_pence,status,expires_at)
      values(item.id,actor,item.seller_id,p_request,item.title,item.price_pence,settings.fee_pence,settings.delivery_pence,'reserved',now()+interval '15 minutes')
      returning * into ord;
    update public.test_listings set status='reserved',reserved_until=ord.expires_at where id=item.id;
    return to_jsonb(ord);
  end if;
  select * into ord from public.test_orders where id=p_order;
  if p_action in ('pay','fail','cancel') then
    if ord.buyer_id<>actor then raise exception 'Buyer action only' using errcode='42501'; end if;
    if (p_action='pay' and ord.status in ('paid','dispatched','delivered'))
      or (p_action='fail' and ord.status='failed') or (p_action='cancel' and ord.status='cancelled') then return to_jsonb(ord); end if;
    if ord.status<>'reserved' then return to_jsonb(ord); end if;
    update public.test_orders set status=case p_action when 'pay' then 'paid' when 'fail' then 'failed' else 'cancelled' end,
      updated_at=now() where id=ord.id returning * into ord;
    update public.test_listings set status=case when p_action='pay' then 'sold' else 'active' end,reserved_until=null where id=item.id;
  elsif p_action='dispatch' then
    if actor<>ord.seller_id then raise exception 'Seller action only' using errcode='42501'; end if;
    if ord.status='paid' then update public.test_orders set status='dispatched',updated_at=now() where id=ord.id returning * into ord;
    elsif ord.status not in ('dispatched','delivered') then raise exception 'Order is not paid' using errcode='23514'; end if;
  elsif p_action='deliver' then
    if actor<>ord.buyer_id then raise exception 'Buyer action only' using errcode='42501'; end if;
    if ord.status='dispatched' then update public.test_orders set status='delivered',updated_at=now() where id=ord.id returning * into ord;
    elsif ord.status<>'delivered' then raise exception 'Order is not dispatched' using errcode='23514'; end if;
  else raise exception 'Invalid test action' using errcode='22023';
  end if;
  return to_jsonb(ord);
end;
$$;
revoke all on function private.test_checkout(text,uuid,uuid,uuid,text,integer) from public,anon,authenticated;
grant usage on schema private to authenticated;
grant execute on function private.test_checkout(text,uuid,uuid,uuid,text,integer) to authenticated;
create function public.test_checkout(p_action text,p_listing uuid default null,p_request uuid default null,p_order uuid default null,p_title text default null,p_price integer default null)
returns jsonb language sql security invoker set search_path='' as $$
  select private.test_checkout(p_action,p_listing,p_request,p_order,p_title,p_price);
$$;
revoke all on function public.test_checkout(text,uuid,uuid,uuid,text,integer) from public,anon,authenticated;
grant execute on function public.test_checkout(text,uuid,uuid,uuid,text,integer) to authenticated;
commit;

-- ===== 20261117150000_orders_escrow.sql =====
-- Real marketplace orders with held funds.
-- The database decides what should happen to the money (funds column); a server
-- worker performs it with the payment provider and reports back through
-- order_system(). Nothing here talks to a provider, and checkout starts disabled.
begin;
create schema if not exists private;

create table private.marketplace_settings (
  singleton boolean primary key default true check (singleton),
  checkout_enabled boolean not null default false,
  fee_fixed_pence integer not null default 70 check (fee_fixed_pence between 0 and 100000),
  fee_bps integer not null default 500 check (fee_bps between 0 and 5000),
  delivery_pence integer not null default 595 check (delivery_pence between 0 and 100000),
  reservation_minutes integer not null default 35 check (reservation_minutes between 5 and 1440),
  dispatch_days integer not null default 5 check (dispatch_days between 1 and 30),
  delivery_timeout_days integer not null default 10 check (delivery_timeout_days between 1 and 60),
  hold_hours integer not null default 48 check (hold_hours between 0 and 720)
);
insert into private.marketplace_settings default values;
alter table private.marketplace_settings enable row level security;
revoke all on private.marketplace_settings from public, anon, authenticated;

-- Listings gain reserved and sold. Only order functions may enter or leave them.
alter table public.listings drop constraint listings_status_check;
alter table public.listings add constraint listings_status_check
  check (status in ('active', 'reserved', 'sold', 'archived'));

create function private.guard_listing_status() returns trigger
language plpgsql set search_path = '' as $$
begin
  -- Order functions run as their owner; direct client writes run as these roles.
  if current_user in ('anon', 'authenticated')
     and (old.status in ('reserved', 'sold') or new.status in ('reserved', 'sold')) then
    raise exception 'This listing is part of an order' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function private.guard_listing_status() from public, anon, authenticated;
create trigger listings_status_guard before update on public.listings
  for each row execute function private.guard_listing_status();

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.listings(id),
  buyer_id uuid not null references public.profiles(id),
  seller_id uuid not null references public.profiles(id),
  request_id uuid not null,
  title text not null,
  item_pence integer not null check (item_pence > 0),
  fee_pence integer not null check (fee_pence >= 0),
  delivery_pence integer not null check (delivery_pence >= 0),
  total_pence integer generated always as (item_pence + fee_pence + delivery_pence) stored,
  -- Fulfilment and money are tracked separately.
  status text not null default 'awaiting_payment' check (status in
    ('awaiting_payment', 'paid', 'dispatched', 'delivered', 'completed', 'disputed', 'cancelled', 'expired')),
  funds text not null default 'none' check (funds in
    ('none', 'held', 'release_due', 'released', 'refund_due', 'refunded')),
  expires_at timestamptz not null,
  paid_at timestamptz,
  dispatch_by timestamptz,
  dispatched_at timestamptz,
  tracking text check (char_length(tracking) <= 100),
  delivered_at timestamptz,
  release_at timestamptz,
  completed_at timestamptz,
  issue text check (char_length(issue) <= 2000),
  checkout_ref text,          -- provider checkout session, so a cancelled order can close it
  payment_ref text,
  transfer_ref text,
  refund_ref text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (buyer_id, request_id),
  check (buyer_id <> seller_id)
);
create unique index orders_one_live_per_listing on public.orders (listing_id)
  where status in ('awaiting_payment', 'paid', 'dispatched', 'delivered', 'completed', 'disputed');
create index orders_buyer on public.orders (buyer_id, created_at desc);
create index orders_seller on public.orders (seller_id, created_at desc);
create index orders_money_work on public.orders (funds) where funds in ('release_due', 'refund_due');
create index orders_open on public.orders (status) where status in ('awaiting_payment', 'paid', 'dispatched', 'delivered');
create trigger orders_updated before update on public.orders
  for each row execute function public.set_updated_at();

create table public.order_events (
  id bigint generated always as identity primary key,
  order_id uuid not null references public.orders(id),
  actor_id uuid,              -- null for the system (webhook, sweep, support)
  action text not null,
  status text not null,
  funds text not null,
  note text,
  created_at timestamptz not null default now()
);
create index order_events_order on public.order_events (order_id, id);

-- One row per provider event, so a repeated webhook is recognised and ignored.
create table public.payment_events (
  event_id text primary key,
  order_id uuid references public.orders(id),
  action text not null,
  received_at timestamptz not null default now()
);

-- Delivery address: written by the server from the provider's checkout, shown to
-- the seller only while they need it to post the item.
create table public.order_addresses (
  order_id uuid primary key references public.orders(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  line1 text not null check (char_length(line1) between 1 and 120),
  line2 text check (char_length(line2) <= 120),
  city text not null check (char_length(city) between 1 and 80),
  postcode text not null check (char_length(postcode) between 2 and 12),
  country text not null default 'GB' check (country = 'GB'),
  created_at timestamptz not null default now()
);
alter table public.order_addresses enable row level security;
revoke all on public.order_addresses from public, anon, authenticated;
grant select on public.order_addresses to authenticated;
grant all on public.order_addresses to service_role;
create policy order_address_participants on public.order_addresses for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and (
    o.buyer_id = (select auth.uid())
    or (o.seller_id = (select auth.uid()) and o.status in ('paid', 'dispatched', 'delivered', 'disputed')))));

-- The seller's payout account with the payment provider. Funds wait in
-- release_due until payouts_enabled is true.
create table public.seller_accounts (
  seller_id uuid primary key references public.profiles(id),
  provider_account text not null unique,
  payouts_enabled boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger seller_accounts_updated before update on public.seller_accounts
  for each row execute function public.set_updated_at();
alter table public.seller_accounts enable row level security;
revoke all on public.seller_accounts from public, anon, authenticated;
grant select (seller_id, payouts_enabled) on public.seller_accounts to authenticated;
grant all on public.seller_accounts to service_role;
create policy seller_account_own on public.seller_accounts for select to authenticated
  using (seller_id = (select auth.uid()));

alter table public.orders enable row level security;
alter table public.order_events enable row level security;
alter table public.payment_events enable row level security;
revoke all on public.orders, public.order_events, public.payment_events from public, anon, authenticated;
grant select on public.orders, public.order_events to authenticated;
grant all on public.orders, public.order_events, public.payment_events to service_role;
create policy orders_participants on public.orders for select to authenticated
  using ((select auth.uid()) in (buyer_id, seller_id));
create policy order_events_participants on public.order_events for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and (select auth.uid()) in (o.buyer_id, o.seller_id)));

create function private.order_fee(p_item integer, s private.marketplace_settings) returns integer
language sql immutable set search_path = '' as $$
  select s.fee_fixed_pence + round(p_item::numeric * s.fee_bps / 10000)::integer;
$$;

create function private.log_order(o public.orders, p_actor uuid, p_action text, p_note text default null) returns void
language sql set search_path = '' as $$
  insert into public.order_events (order_id, actor_id, action, status, funds, note)
  values (o.id, p_actor, p_action, o.status, o.funds, p_note);
$$;

revoke all on function private.order_fee(integer, private.marketplace_settings) from public, anon, authenticated;
revoke all on function private.log_order(public.orders, uuid, text, text) from public, anon, authenticated;

-- Buyer and seller actions. Money never moves here: the furthest a client can
-- go is to make funds release_due (buyer accepting) or freeze them (issue).
create function public.order_action(p_action text, p_listing uuid default null, p_request uuid default null,
  p_order uuid default null, p_text text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := auth.uid();
  s private.marketplace_settings;
  item public.listings;
  ord public.orders;
  note text := nullif(btrim(coalesce(p_text, '')), '');
begin
  if actor is null or not exists (select 1 from auth.users where id = actor and email_confirmed_at is not null) then
    raise exception 'Confirm your email before buying or selling' using errcode = '42501';
  end if;
  select * into s from private.marketplace_settings where singleton;

  if p_action in ('quote', 'reserve') then
    if not s.checkout_enabled then raise exception 'Checkout is not open yet' using errcode = '55000'; end if;
    select * into item from public.listings where id = p_listing for update;
    if not found then raise exception 'Listing unavailable' using errcode = 'P0002'; end if;
    if item.seller_id = actor then raise exception 'You cannot buy your own listing' using errcode = '42501'; end if;
    if p_action = 'reserve' then
      if p_request is null then raise exception 'Request ID required' using errcode = '22023'; end if;
      -- A retried request returns the order it already created.
      select * into ord from public.orders where buyer_id = actor and request_id = p_request;
      if found then
        if ord.listing_id <> item.id then raise exception 'Request already used' using errcode = '22023'; end if;
        return to_jsonb(ord);
      end if;
    end if;
    -- Release a lapsed reservation before judging availability.
    update public.orders set status = 'expired'
      where listing_id = item.id and status = 'awaiting_payment' and expires_at <= now();
    if found and item.status = 'reserved' then
      update public.listings set status = 'active' where id = item.id returning * into item;
    end if;
    if item.status <> 'active' then raise exception 'This item is already reserved or sold' using errcode = '23505'; end if;
    if p_action = 'quote' then
      return jsonb_build_object('title', item.brand || ' ' || item.name, 'item_pence', item.price_pence,
        'fee_pence', private.order_fee(item.price_pence, s), 'delivery_pence', s.delivery_pence,
        'total_pence', item.price_pence + private.order_fee(item.price_pence, s) + s.delivery_pence,
        'hold_hours', s.hold_hours);
    end if;
    if exists (select 1 from public.user_blocks where (blocker_id = actor and blocked_id = item.seller_id)
        or (blocker_id = item.seller_id and blocked_id = actor)) then
      raise exception 'This item is unavailable to you' using errcode = '42501';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('order-buyer:' || actor::text, 0));
    if (select count(*) from public.orders where buyer_id = actor and created_at > now() - interval '1 hour') >= 10 then
      raise exception 'Too many checkouts started. Please wait.' using errcode = 'P0001';
    end if;
    insert into public.orders (listing_id, buyer_id, seller_id, request_id, title, item_pence, fee_pence, delivery_pence, expires_at)
      values (item.id, actor, item.seller_id, p_request, item.brand || ' ' || item.name, item.price_pence,
        private.order_fee(item.price_pence, s), s.delivery_pence, now() + make_interval(mins => s.reservation_minutes))
      returning * into ord;
    update public.listings set status = 'reserved' where id = item.id;
    perform private.log_order(ord, actor, 'reserve');
    return to_jsonb(ord);
  end if;

  select * into ord from public.orders where id = p_order and actor in (buyer_id, seller_id) for update;
  if not found then raise exception 'Order unavailable' using errcode = 'P0002'; end if;

  if p_action = 'cancel' then
    -- Only before payment. After payment, cancellation is a refund decided by rules or support.
    if actor <> ord.buyer_id then raise exception 'Buyer action only' using errcode = '42501'; end if;
    if ord.status = 'cancelled' then return to_jsonb(ord); end if;
    if ord.status <> 'awaiting_payment' then raise exception 'This order can no longer be cancelled here' using errcode = '23514'; end if;
    update public.orders set status = 'cancelled' where id = ord.id returning * into ord;
    update public.listings set status = 'active' where id = ord.listing_id and status = 'reserved';
  elsif p_action = 'dispatch' then
    if actor <> ord.seller_id then raise exception 'Seller action only' using errcode = '42501'; end if;
    if ord.status in ('dispatched', 'delivered', 'completed') then return to_jsonb(ord); end if;
    if ord.status <> 'paid' then raise exception 'Order is not awaiting dispatch' using errcode = '23514'; end if;
    -- Tracked postage is mandatory: it is the seller's proof of posting.
    if note is null or char_length(note) < 6 then raise exception 'Enter the carrier and tracking number' using errcode = '22023'; end if;
    update public.orders set status = 'dispatched', dispatched_at = now(), tracking = left(note, 100)
      where id = ord.id returning * into ord;
  elsif p_action = 'confirm_delivery' then
    if actor <> ord.buyer_id then raise exception 'Buyer action only' using errcode = '42501'; end if;
    if ord.status in ('delivered', 'completed') then return to_jsonb(ord); end if;
    if ord.status <> 'dispatched' then raise exception 'Order is not in transit' using errcode = '23514'; end if;
    update public.orders set status = 'delivered', delivered_at = now(),
        release_at = now() + make_interval(hours => s.hold_hours)
      where id = ord.id returning * into ord;
  elsif p_action = 'accept' then
    -- Buyer is happy: end the hold early.
    if actor <> ord.buyer_id then raise exception 'Buyer action only' using errcode = '42501'; end if;
    if ord.status = 'completed' then return to_jsonb(ord); end if;
    if ord.status not in ('dispatched', 'delivered') then raise exception 'Order cannot be completed yet' using errcode = '23514'; end if;
    update public.orders set status = 'completed', funds = 'release_due', completed_at = now(),
        delivered_at = coalesce(delivered_at, now())
      where id = ord.id returning * into ord;
  elsif p_action = 'report_issue' then
    if actor <> ord.buyer_id then raise exception 'Buyer action only' using errcode = '42501'; end if;
    if ord.status = 'disputed' then return to_jsonb(ord); end if;
    if ord.status not in ('dispatched', 'delivered') then raise exception 'The issue window for this order is closed' using errcode = '23514'; end if;
    if note is null then raise exception 'Describe the issue' using errcode = '22023'; end if;
    update public.orders set status = 'disputed', issue = left(note, 2000), release_at = null
      where id = ord.id returning * into ord;
  else
    raise exception 'Invalid order action' using errcode = '22023';
  end if;
  perform private.log_order(ord, actor, p_action, note);
  return to_jsonb(ord);
end;
$$;
revoke all on function public.order_action(text, uuid, uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.order_action(text, uuid, uuid, uuid, text) to authenticated;

-- Server-only transitions: verified payment webhooks, the money worker, carrier
-- updates and support decisions. p_event makes provider events repeat-safe.
create function public.order_system(p_action text, p_order uuid, p_ref text default null, p_event text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  s private.marketplace_settings;
  ord public.orders;
  item public.listings;
begin
  select * into s from private.marketplace_settings where singleton;
  select * into ord from public.orders where id = p_order for update;
  if not found then raise exception 'Order not found' using errcode = 'P0002'; end if;
  if p_event is not null then
    insert into public.payment_events (event_id, order_id, action) values (p_event, ord.id, p_action)
      on conflict do nothing;
    if not found then return to_jsonb(ord); end if;
  end if;
  select * into item from public.listings where id = ord.listing_id for update;

  if p_action = 'payment_succeeded' then
    if ord.funds <> 'none' then return to_jsonb(ord); end if;
    if ord.status = 'awaiting_payment' then
      null;
    elsif ord.status in ('expired', 'cancelled') and item.status = 'active' then
      -- Late success and the item is still free: honour the purchase.
      null;
    elsif ord.status in ('expired', 'cancelled') then
      -- Late success but the item has gone: take no sale, give the money back.
      update public.orders set funds = 'refund_due', payment_ref = p_ref, paid_at = now()
        where id = ord.id returning * into ord;
      perform private.log_order(ord, null, 'late_payment_refund', p_ref);
      return to_jsonb(ord);
    else
      return to_jsonb(ord);
    end if;
    update public.orders set status = 'paid', funds = 'held', payment_ref = p_ref, paid_at = now(),
        dispatch_by = now() + make_interval(days => s.dispatch_days)
      where id = ord.id returning * into ord;
    update public.listings set status = 'sold' where id = item.id;
  elsif p_action = 'payment_failed' then
    if ord.status <> 'awaiting_payment' then return to_jsonb(ord); end if;
    update public.orders set status = 'cancelled' where id = ord.id returning * into ord;
    update public.listings set status = 'active' where id = item.id and status = 'reserved';
  elsif p_action = 'mark_delivered' then
    if ord.status <> 'dispatched' then return to_jsonb(ord); end if;
    update public.orders set status = 'delivered', delivered_at = now(),
        release_at = now() + make_interval(hours => s.hold_hours)
      where id = ord.id returning * into ord;
  elsif p_action = 'released' then
    if ord.funds = 'released' then return to_jsonb(ord); end if;
    if ord.funds <> 'release_due' then raise exception 'Funds are not due for release' using errcode = '23514'; end if;
    update public.orders set funds = 'released', transfer_ref = p_ref where id = ord.id returning * into ord;
  elsif p_action = 'refunded' then
    if ord.funds = 'refunded' then return to_jsonb(ord); end if;
    if ord.funds <> 'refund_due' then raise exception 'No refund is due' using errcode = '23514'; end if;
    update public.orders set funds = 'refunded', refund_ref = p_ref where id = ord.id returning * into ord;
  elsif p_action = 'chargeback' then
    -- The buyer's bank disputed the charge. Freeze anything not yet released;
    -- if already released, the event is still recorded for support.
    if ord.funds = 'held' and ord.status in ('paid', 'dispatched', 'delivered') then
      update public.orders set status = 'disputed', release_at = null,
          issue = coalesce(issue, 'Card dispute opened with the payment provider')
        where id = ord.id returning * into ord;
    end if;
  elsif p_action = 'resolve_release' then
    if ord.status <> 'disputed' or ord.funds <> 'held' then raise exception 'Order is not in dispute' using errcode = '23514'; end if;
    update public.orders set status = 'completed', funds = 'release_due', completed_at = now()
      where id = ord.id returning * into ord;
  elsif p_action = 'resolve_refund' then
    -- Support refund of any order still holding funds. Before dispatch the item
    -- goes back on sale; afterwards the seller relists once it is returned.
    if ord.funds <> 'held' then raise exception 'No held funds to refund' using errcode = '23514'; end if;
    update public.listings set status = case when ord.status = 'paid' then 'active' else 'archived' end where id = item.id;
    update public.orders set status = 'cancelled', funds = 'refund_due' where id = ord.id returning * into ord;
  else
    raise exception 'Invalid system action' using errcode = '22023';
  end if;
  perform private.log_order(ord, null, p_action, p_ref);
  return to_jsonb(ord);
end;
$$;
revoke all on function public.order_system(text, uuid, text, text) from public, anon, authenticated;
grant execute on function public.order_system(text, uuid, text, text) to service_role;

-- Time-based rules. Safe to run as often as wanted.
create function public.order_sweep() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s private.marketplace_settings;
  ord public.orders;
  n_expired integer := 0; n_undispatched integer := 0; n_delivered integer := 0; n_released integer := 0;
begin
  select * into s from private.marketplace_settings where singleton;
  for ord in select * from public.orders where status = 'awaiting_payment' and expires_at <= now() for update skip locked loop
    update public.orders set status = 'expired' where id = ord.id returning * into ord;
    update public.listings set status = 'active' where id = ord.listing_id and status = 'reserved';
    perform private.log_order(ord, null, 'expire');
    n_expired := n_expired + 1;
  end loop;
  for ord in select * from public.orders where status = 'paid' and dispatch_by <= now() for update skip locked loop
    update public.orders set status = 'cancelled', funds = 'refund_due' where id = ord.id returning * into ord;
    update public.listings set status = 'active' where id = ord.listing_id and status = 'sold';
    perform private.log_order(ord, null, 'not_dispatched_refund');
    n_undispatched := n_undispatched + 1;
  end loop;
  for ord in select * from public.orders where status = 'dispatched'
      and dispatched_at <= now() - make_interval(days => s.delivery_timeout_days) for update skip locked loop
    update public.orders set status = 'delivered', delivered_at = now(),
        release_at = now() + make_interval(hours => s.hold_hours)
      where id = ord.id returning * into ord;
    perform private.log_order(ord, null, 'assume_delivered');
    n_delivered := n_delivered + 1;
  end loop;
  for ord in select * from public.orders where status = 'delivered' and release_at <= now() for update skip locked loop
    update public.orders set status = 'completed', funds = 'release_due', completed_at = now()
      where id = ord.id returning * into ord;
    perform private.log_order(ord, null, 'hold_elapsed');
    n_released := n_released + 1;
  end loop;
  return jsonb_build_object('expired', n_expired, 'not_dispatched', n_undispatched,
    'assumed_delivered', n_delivered, 'release_due', n_released);
end;
$$;
revoke all on function public.order_sweep() from public, anon, authenticated;
grant execute on function public.order_sweep() to service_role;

commit;

-- ===== 20261117180000_support_and_clawback.sql =====
-- Support tools, payout clawback, and removal of the retired checkout simulation.
-- Safe to run once on a database that already has 20261117150000_orders_escrow.sql.
begin;

-- 1. Retire the simulation (its tables are test-only and separate from real listings).
drop function if exists public.test_checkout(text, uuid, uuid, uuid, text, integer);
drop function if exists private.test_checkout(text, uuid, uuid, uuid, text, integer);
drop table if exists public.test_orders;
drop table if exists public.test_listings;
drop table if exists private.test_checkout_settings;
-- The simulation was the only reason signed-in users could reach this schema.
revoke usage on schema private from authenticated;

-- 2. Settings the server may read and the support screen may switch.
create function public.marketplace_settings() returns jsonb
language sql stable security definer set search_path = '' as $$
  select to_jsonb(s) - 'singleton' from private.marketplace_settings s where singleton;
$$;
create function public.set_checkout_enabled(p_enabled boolean) returns jsonb
language sql security definer set search_path = '' as $$
  update private.marketplace_settings set checkout_enabled = p_enabled where singleton;
  select public.marketplace_settings();
$$;
revoke all on function public.marketplace_settings() from public, anon, authenticated;
revoke all on function public.set_checkout_enabled(boolean) from public, anon, authenticated;
grant execute on function public.marketplace_settings() to service_role;
grant execute on function public.set_checkout_enabled(boolean) to service_role;

-- 3. Who did what in the support screen.
create table public.admin_actions (
  id bigint generated always as identity primary key,
  admin_id uuid not null,
  action text not null,
  target text not null,
  note text,
  created_at timestamptz not null default now()
);
alter table public.admin_actions enable row level security;
revoke all on public.admin_actions from public, anon, authenticated;
grant select, insert on public.admin_actions to service_role;

-- 4. Taking a payout back. Needed when the buyer's bank disputes a charge, or support
-- refunds an order, after the seller has already been paid.
alter table public.orders drop constraint orders_funds_check;
alter table public.orders add constraint orders_funds_check check (funds in
  ('none', 'held', 'release_due', 'released', 'refund_due', 'refunded', 'reversal_due', 'reversed'));
alter table public.orders
  add column reversal_ref text,
  add column refund_after_reversal boolean not null default false;
drop index public.orders_money_work;
create index orders_money_work on public.orders (funds) where funds in ('release_due', 'refund_due', 'reversal_due');

create function public.order_clawback(p_action text, p_order uuid, p_ref text default null, p_refund boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare ord public.orders;
begin
  select * into ord from public.orders where id = p_order for update;
  if not found then raise exception 'Order not found' using errcode = 'P0002'; end if;
  if p_action = 'start' then
    if ord.funds = 'release_due' then
      -- Not paid out yet: simply stop the payout and hold the money for support.
      update public.orders set funds = 'held', status = 'disputed', release_at = null,
          issue = coalesce(issue, 'Payout stopped for review')
        where id = ord.id returning * into ord;
      insert into public.order_events (order_id, action, status, funds, note) values (ord.id, 'payout_stopped', ord.status, ord.funds, p_ref);
    elsif ord.funds = 'released' then
      update public.orders set funds = 'reversal_due', status = 'disputed', refund_after_reversal = p_refund,
          issue = coalesce(issue, 'Payout being taken back for review')
        where id = ord.id returning * into ord;
      insert into public.order_events (order_id, action, status, funds, note) values (ord.id, 'clawback_started', ord.status, ord.funds, p_ref);
    end if;
  elsif p_action = 'reversed' then
    if ord.funds in ('reversed', 'refund_due', 'refunded') and ord.reversal_ref is not null then return to_jsonb(ord); end if;
    if ord.funds <> 'reversal_due' then raise exception 'No payout is being taken back' using errcode = '23514'; end if;
    update public.orders set reversal_ref = p_ref,
        funds = case when refund_after_reversal then 'refund_due' else 'reversed' end,
        status = case when refund_after_reversal then 'cancelled' else status end
      where id = ord.id returning * into ord;
    insert into public.order_events (order_id, action, status, funds, note) values (ord.id, 'payout_reversed', ord.status, ord.funds, p_ref);
  else
    raise exception 'Invalid clawback action' using errcode = '22023';
  end if;
  return to_jsonb(ord);
end;
$$;
revoke all on function public.order_clawback(text, uuid, text, boolean) from public, anon, authenticated;
grant execute on function public.order_clawback(text, uuid, text, boolean) to service_role;

-- 5. Reviews: one from the buyer and one from the seller, only after an order completes.
create table public.reviews (
  order_id uuid not null references public.orders(id),
  reviewer_id uuid not null references public.profiles(id),
  reviewee_id uuid not null references public.profiles(id),
  rating smallint not null check (rating between 1 and 5),
  comment text not null default '' check (char_length(comment) <= 500),
  created_at timestamptz not null default now(),
  primary key (order_id, reviewer_id),
  check (reviewer_id <> reviewee_id)
);
create index reviews_reviewee on public.reviews (reviewee_id, created_at desc);
alter table public.reviews enable row level security;
revoke all on public.reviews from public, anon, authenticated;
-- Ratings are public; who wrote each one, and for which order, is visible only to signed-in members.
grant select (reviewee_id, rating, comment, created_at) on public.reviews to anon;
grant select on public.reviews to authenticated;
grant all on public.reviews to service_role;
create policy reviews_public_read on public.reviews for select to anon, authenticated using (true);

create function public.leave_review(p_order uuid, p_rating integer, p_comment text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := auth.uid();
  ord public.orders;
  made public.reviews;
begin
  if actor is null or not exists (select 1 from auth.users where id = actor and email_confirmed_at is not null) then
    raise exception 'Confirm your email before leaving a review' using errcode = '42501';
  end if;
  select * into ord from public.orders where id = p_order and actor in (buyer_id, seller_id);
  if not found then raise exception 'Order unavailable' using errcode = 'P0002'; end if;
  if ord.status <> 'completed' then raise exception 'You can leave a review once the order is complete' using errcode = '23514'; end if;
  if p_rating is null or p_rating not between 1 and 5 then raise exception 'Choose a rating from 1 to 5' using errcode = '22023'; end if;
  if exists (select 1 from public.reviews where order_id = ord.id and reviewer_id = actor) then
    raise exception 'You have already reviewed this order' using errcode = '23505';
  end if;
  insert into public.reviews (order_id, reviewer_id, reviewee_id, rating, comment)
    values (ord.id, actor, case when actor = ord.buyer_id then ord.seller_id else ord.buyer_id end, p_rating, left(btrim(coalesce(p_comment, '')), 500))
    returning * into made;
  return to_jsonb(made);
end;
$$;
revoke all on function public.leave_review(uuid, integer, text) from public, anon, authenticated;
grant execute on function public.leave_review(uuid, integer, text) to authenticated;

commit;

-- ===== 20261117210000_accounts_and_emails.sql =====
-- Account suspension and deletion, and the queue of emails to send.
-- Run once, after 20261117180000_support_and_clawback.sql.
begin;

-- 1. Suspended or deleted accounts keep their history but can no longer act.
alter table public.profiles
  add column suspended_at timestamptz,
  add column deleted_at timestamptz;

-- Every "may this person list, message, save or report" rule already calls this function,
-- so tightening it here applies suspension everywhere at once.
create or replace function public.is_verified_seller() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from auth.users u join public.profiles p on p.id = u.id
    where u.id = (select auth.uid()) and u.email_confirmed_at is not null
      and p.suspended_at is null and p.deleted_at is null);
$$;

-- New purchases are refused if either side is suspended or deleted. Orders already
-- under way carry on, so nobody's money or parcel is stranded.
create function private.guard_order_parties() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from public.profiles where id in (new.buyer_id, new.seller_id)
      and (suspended_at is not null or deleted_at is not null)) then
    raise exception 'This item cannot be bought at the moment' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function private.guard_order_parties() from public, anon, authenticated;
create trigger orders_party_guard before insert on public.orders
  for each row execute function private.guard_order_parties();

-- 2. Emails are queued here by the database and sent by the server, so a slow or failing
-- email provider can never block a payment, a message or an order step.
create table public.email_outbox (
  id bigint generated always as identity primary key,
  user_id uuid not null,
  template text not null,
  data jsonb not null default '{}',
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  attempts integer not null default 0,
  last_error text
);
create index email_outbox_pending on public.email_outbox (id) where sent_at is null;
alter table public.email_outbox enable row level security;
revoke all on public.email_outbox from public, anon, authenticated;
grant select, insert, update, delete on public.email_outbox to service_role;

create function private.queue_order_email() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  o public.orders;
  info jsonb;
  to_buyer text;
  to_seller text;
begin
  select * into o from public.orders where id = new.order_id;
  if new.action = 'payment_succeeded' then to_buyer := 'order_paid'; to_seller := 'order_sold';
  elsif new.action = 'dispatch' then to_buyer := 'order_posted';
  elsif new.action = 'confirm_delivery' then to_seller := 'order_delivered';
  elsif new.action in ('assume_delivered', 'mark_delivered') then to_buyer := 'order_check'; to_seller := 'order_delivered';
  elsif new.action in ('accept', 'hold_elapsed', 'resolve_release') then to_seller := 'order_completed';
  elsif new.action = 'released' then to_seller := 'order_paid_out';
  elsif new.action = 'report_issue' then to_seller := 'order_issue';
  elsif new.action in ('not_dispatched_refund', 'resolve_refund') then to_buyer := 'order_refunding'; to_seller := 'order_cancelled';
  elsif new.action = 'late_payment_refund' then to_buyer := 'order_refunding';
  elsif new.action = 'refunded' then to_buyer := 'order_refunded';
  else return new;
  end if;
  info := jsonb_build_object('order_id', o.id, 'title', o.title, 'total_pence', o.total_pence,
    'seller_pence', o.item_pence + o.delivery_pence, 'tracking', o.tracking,
    'dispatch_by', o.dispatch_by, 'release_at', o.release_at);
  if to_buyer is not null then insert into public.email_outbox (user_id, template, data) values (o.buyer_id, to_buyer, info); end if;
  if to_seller is not null then insert into public.email_outbox (user_id, template, data) values (o.seller_id, to_seller, info); end if;
  return new;
end;
$$;
revoke all on function private.queue_order_email() from public, anon, authenticated;
create trigger order_events_email after insert on public.order_events
  for each row execute function private.queue_order_email();

-- A new message emails the other person, at most once an hour per conversation.
create function private.queue_message_email() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  thread public.conversations;
  recipient uuid;
begin
  select * into thread from public.conversations where id = new.conversation_id;
  recipient := case when new.sender_id = thread.buyer_id then thread.seller_id else thread.buyer_id end;
  if not exists (select 1 from public.email_outbox where user_id = recipient and template = 'new_message'
      and data ->> 'conversation_id' = thread.id::text and created_at > now() - interval '1 hour') then
    insert into public.email_outbox (user_id, template, data)
      values (recipient, 'new_message', jsonb_build_object('conversation_id', thread.id, 'title', thread.listing_title));
  end if;
  return new;
end;
$$;
revoke all on function private.queue_message_email() from public, anon, authenticated;
create trigger messages_email after insert on public.messages
  for each row execute function private.queue_message_email();

commit;
